// virtual/override — runtime dispatch
class Animal { public virtual string Sound() => "..."; }
class Dog : Animal { public override string Sound() => "Woof"; }
Animal a = new Dog();
a.Sound();  // "Woof" — override found at runtime

// new (hiding) — compile-time dispatch
class Cat : Animal { public new string Sound() => "Meow"; }
Animal c = new Cat();
c.Sound();  // "..." — base method, because reference type = Animal

// Interface with default impl (C# 8+)
interface ILogger {
  void Log(string msg);
  void LogError(string msg) => Log("[ERROR] " + msg);  // default
}
